"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["89854"],{72657(e,s,n){n.r(s),n.d(s,{metadata:()=>a,default:()=>u,frontMatter:()=>o,contentTitle:()=>r,toc:()=>h,assets:()=>l});var a=JSON.parse('{"id":"tangfen/qys","title":"","description":"Qingyushan2 thinks \\"discussing Marx\'s theory is not opposing Marx.\\" First, he probably treats \\"opposing Marx\\" as some kind of crime. But Chinese law apparently doesn\'t include a crime called \\"opposing Marx.\\" Furthermore, opposing Marx and opposing Marxism are different. Marxism is already at minimum a political concept, whereas Marx is just a person!","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/qys.md","sourceDirName":"tangfen","slug":"/tangfen/qys","permalink":"/en/tangfen/qys","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"qys","title":"","hide_table_of_contents":true,"sidebar_label":"Qingyushan2, discussing Marxist theory naturally includes anti-Marxist views!"},"sidebar":"tangfenSidebar","previous":{"title":"To all who distort Marx: on \\"Marx is not a Marxist\\"","permalink":"/en/tangfen/tomarxtwisters"},"next":{"title":"The Ah Q spirit of anti-Marxists like Dushulang, Yixuan, Banong Guocui!","permalink":"/en/tangfen/aqspirit"}}'),t=n(74848),i=n(28453);let o={id:"qys",title:"",hide_table_of_contents:!0,sidebar_label:"Qingyushan2, discussing Marxist theory naturally includes anti-Marxist views!"},r="Qingyushan2, Discussing Marx's Theory Naturally Includes Those Who Oppose Marx!",l={},h=[];function c(e){let s={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(s.header,{children:(0,t.jsx)(s.h1,{id:"qingyushan2-discussing-marxs-theory-naturally-includes-those-who-oppose-marx",children:"Qingyushan2, Discussing Marx's Theory Naturally Includes Those Who Oppose Marx!"})}),"\n",(0,t.jsx)(s.p,{children:'Qingyushan2 thinks "discussing Marx\'s theory is not opposing Marx." First, he probably treats "opposing Marx" as some kind of crime. But Chinese law apparently doesn\'t include a crime called "opposing Marx." Furthermore, opposing Marx and opposing Marxism are different. Marxism is already at minimum a political concept, whereas Marx is just a person!'}),"\n",(0,t.jsx)(s.p,{children:"In any discussion of anyone's theory, there are naturally those who oppose it. If there's no opposition, and everything is affirmative, then what's there to discuss? So discussing Marx's theory naturally includes those who oppose Marx! For example, here, *** opposes Marx every day and openly admits it, declaring Marx to be fallacious. Of course there are also those who have internally opposed Marx thousands of times but put on a front of discussion while secretly playing tricks of substitution and distortion -- such people are even worse than Yunguzi. Even worse are those who come with the explicit mission of opposing Marx -- such people's noses have been trained to the point that anything with even a whiff of Marx, regardless of what's being said about Marx, triggers them to attack!"}),"\n",(0,t.jsx)(s.p,{children:"But discussions about Marx differ fundamentally from discussions of other issues, because the name Marx itself has become conventionally politicized. Although this convention is entirely unreasonable, it is reality. Therefore, all discussions about Marx are actually clearly delineated. And Marx's theory itself is not ordinary scholastic philosophy -- it's not purely exchanging idle chatter. The revolutionary and critical nature of Marx's theory determines that all discussions about Marx have real-world significance!"}),"\n",(0,t.jsx)(s.p,{children:"Scholasticizing Marx's theory is also a habitual trick of all who distort and oppose Marx. On this matter of cardinal importance, there can be no room for \"village worthies\"! To borrow Miss Chan's phrasing: the scholastic Marx is not Marx. In discussions of Marx, the pro and con cannot be reconciled. Marx does not mix mud, and discussing Marx even less so!"})]})}function u(e={}){let{wrapper:s}={...(0,i.R)(),...e.components};return s?(0,t.jsx)(s,{...e,children:(0,t.jsx)(c,{...e})}):c(e)}},28453(e,s,n){n.d(s,{R:()=>o,x:()=>r});var a=n(96540);let t={},i=a.createContext(t);function o(e){let s=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(s):{...s,...e}},[s,e])}function r(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),a.createElement(i.Provider,{value:s},e.children)}}}]);